    ms_output.accepted_field_t = ms_state.previous_field_t;
    ms_output.rate_t_s.x = 0.0;
    ms_output.rate_t_s.y = 0.0;
    ms_output.rate_t_s.z = 0.0;
    ms_output.rate_norm_t_s = 0.0;
    ms_output.field_energy_t2 = 0.0;
    return;
}

// 4. Calculate Field Energy
double field_energy = adcs_vec3_dot(ms_input.field_body_t, ms_input.field_body_t);
ms_output.field_energy_t2 = field_energy;

adcs_vec3_t rate_t_s = {0.0, 0.0, 0.0};
double rate_norm = 0.0;

// 5. First Valid Sample Initialization
if (ms_state.mode == MS_EMPTY) {
    ms_state.previous_field_t = *ms_input.field_body_t;
    ms_output.mode = MS_TRACK;
    ms_output.rejects = 0;
    ms_output.rate_t_s = rate_t_s;
    ms_output.rate_norm_t_s = 0.0;
    ms_output.accepted_field_t = ms_state.previous_field_t;
    ms_state.mode = MS_TRACK;
    return;
}

// 6. Rate Calculation
adcs_vec3_t diff = adcs_vec3_sub(ms_input.field_body_t, &ms_state.previous_field_t);
rate_t_s = adcs_vec3_scale(&diff, 1.0 / ms_input.dt_s);
rate_norm = adcs_vec3_norm(&rate_t_s);

ms_output.rate_t_s = rate_t_s;
ms_output.rate_norm_t_s = rate_norm;

// 7. Plausibility Check
if (rate_norm <= ms_config.max_slew_t_s) {
    // Accepted
    ms_state.previous_field_t = *ms_input.field_body_t;
    ms_state.rejects = 0;
    ms_output.mode = MS_TRACK;
    ms_output.rejects = 0;
    ms_output.accepted_field_t = ms_state.previous_field_t;
} else {
    // Rejected
    ms_state.rejects++;
    ms_output.rejects = ms_state.rejects;

    if (ms_state.rejects >= ms_config.max_rejects) {
        // Latch Fault
        ms_output.mode = MS_FAULT;
        ms_output.accepted_field_t = ms_state.previous_field_t;
        ms_state.mode = MS_FAULT;
    } else {
        // Stay in Reject
        ms_output.mode = MS_REJECT;
        ms_output.accepted_field_t = ms_state.previous_field_t;
    }
}
